// Calculate total surface area of the bounding box
real3<T> bbox_size = bmax - bmin;
real3<T> total_sa = real3<T>(
    2.0 * (bbox_size.y * bbox_size.z),
    2.0 * (bbox_size.x * bbox_size.z),
    2.0 * (bbox_size.x * bbox_size.y)
);

// Initialize variables for SAH calculation
int total_primitives = 0;
for (int i = 0; i < bins->size(); ++i) {
    total_primitives += bins->count(i);
}

real3<T> cost_per_axis(0.0);
real3<T> best_cut_pos(0.0);
int best_axis = -1;
real<T> min_cost = std::numeric_limits<real<T>>::max();

// Evaluate each axis
for (int axis = 0; axis < 3; ++axis) {
    real<T> axis_min = (axis == 0) ? bmin.x : ((axis == 1) ? bmin.y : bmin.z);
    real<T> axis_max = (axis == 0) ? bmax.x : ((axis == 1) ? bmax.y : bmax.z);
    real<T> axis_size = axis_max - axis_min;

    // Calculate cost for each possible cut position
    for (int i = 0; i < bins->size(); ++i) {
        real<T> cut_pos = axis_min + (i + 0.5) * axis_size / static_cast<real<T>>(bins->size());
        real<T> left_area = 0.0, right_area = 0.0;
        int left_count = 0, right_count = 0;

        // Calculate left and right areas and primitive counts
        for (int j = 0; j < bins->size(); ++j) {
            real<T> bin_pos = axis_min + (j + 0.5) * axis_size / static_cast<real<T>>(bins->size());
            if (bin_pos < cut_pos) {
                left_area += (j == 0) ? cut_pos - axis_min : std::min(cut_pos, axis_min + (j + 1) * axis_size / static_cast<real<T>>(bins->size())) - std::max(cut_pos, axis_min + j * axis_size / static_cast<real<T>>(bins->size()));
                left_count += bins->count(j);
            } else {
                right_area += (j == bins->size() - 1) ? axis_max - bin_pos : std::min(axis_max, axis_min + (j + 1) * axis_size / static_cast<real<T>>(bins->size())) - std::max(bin_pos, axis_min + j * axis_size / static_cast<real<T>>(bins->size()));
                right_count += bins->count(j);
            }
        }

        // Calculate SAH cost
        real<T> cost = 1.0 + (left_count * left_area + right_count * right_area) / (total_sa * total_primitives);

        // Update best cut if this is better
        if (cost < min_cost) {
            min_cost = cost;
            best_axis = axis;
            best_cut_pos = real3<T>(0.0);
            best_cut_pos[axis] = cut_pos;
        }
    }

    // Store cost for this axis (for comparison)
    cost_per_axis[axis] = min_cost;
}

// Find the axis with minimum cost
real<T> min_axis_cost = std::numeric_limits<real<T>>::max();
for (int axis = 0; axis < 3; ++axis) {
    if (cost_per_axis[axis] < min_axis_cost) {
        min_axis_cost = cost_per_axis[axis];
        best_axis = axis;
    }
}

// Output results
cut_pos[0] = best_cut_pos.x;
cut_pos[1] = best_cut_pos.y;
cut_pos[2] = best_cut_pos.z;
*minCostAxis = best_axis;
return true;
// END_CODE

